#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cmath>
#include <iostream>
#include <stdexcept>
void check(bool ok,const QString& reason){if(!ok)throw std::runtime_error(reason.toStdString());}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument doc;auto sketch=SketchGeometry::addRectangle(SketchGeometry::newFeature(doc.authored()["documentId"].toString(),"XY"),{{"u1Mm",10},{"v1Mm",8},{"u2Mm",30},{"v2Mm",20}});const auto edges=sketch["parameters"].toObject()["entities"].toArray();QJsonArray ids;for(const auto& e:edges)ids.append(e.toObject()["id"]);
 for(const auto& d:QJsonArray{QJsonObject{{"kind","horizontal"},{"entityId",ids[0]},{"valueMm",20}},QJsonObject{{"kind","vertical"},{"entityId",ids[1]},{"valueMm",12}}}){const auto solved=SketchGeometry::addDimension(sketch,d.toObject());check(solved.ok,solved.error);sketch=solved.feature;}
 const auto original=sketch;const auto baseline=SketchGeometry::solveDraft(sketch);check(baseline.ok && baseline.diagnostics["dof"].toInt()==2,"Two translational DOFs");
 auto move=[&](const QJsonObject& before,double x,double y,QJsonArray selected){return SketchGeometry::translateProfile(before,{{"entityIds",selected},{"deltaUMm",x},{"deltaVMm",y}});};
 auto verify=[&](const QJsonObject& now,double x,double y){const auto a=original["parameters"].toObject(),b=now["parameters"].toObject();for(const auto& key:{"entities","constraints","dimensions"})check(a[key]==b[key],"Identity and constraint definitions preserved");const auto ap=a["points"].toArray(),bp=b["points"].toArray();for(int i=0;i<ap.size();++i)check(ap[i].toObject()["id"]==bp[i].toObject()["id"] && std::abs(bp[i].toObject()["uMm"].toDouble()-ap[i].toObject()["uMm"].toDouble()-x)<1e-6 && std::abs(bp[i].toObject()["vMm"].toDouble()-ap[i].toObject()["vMm"].toDouble()-y)<1e-6,"Exact rigid displacement");check(SketchGeometry::evaluateFeature(now).profiles[0].profileId==SketchGeometry::evaluateFeature(original).profiles[0].profileId,"Profile identity");};
 auto first=move(sketch,5,-3,ids);check(first.ok,first.error);verify(first.feature,5,-3);check(first.diagnostics["dof"].toInt()==2,"Move preserves solver freedom");auto second=move(first.feature,2,1,ids);check(second.ok,second.error);verify(second.feature,7,-2);
 for(const auto& selected:QJsonArray{QJsonArray{ids[0],ids[1],ids[2]},QJsonArray{ids[0],ids[1],ids[2],ids[2]},QJsonArray{ids[0],ids[1],ids[2],"foreign-line"}}){const auto bad=move(sketch,5,-3,selected.toArray());check(!bad.ok && bad.feature==sketch,"Invalid selection atomic");}
 check(!move(sketch,0,0,ids).ok,"Zero displacement is refused as a no-op");
 auto shared=SketchGeometry::addLine(sketch,{{"u1Mm",10},{"v1Mm",8},{"u2Mm",2},{"v2Mm",3}});auto bad=move(shared,5,-3,ids);check(!bad.ok && bad.feature==shared,"Shared unselected endpoint refused");
 auto placed=SketchGeometry::withOriginReference(sketch);const auto vertex=edges[0].toObject().value("startPointId");auto dimension=SketchGeometry::addDimension(placed,{{"kind","horizontal"},{"pointIds",QJsonArray{placed["parameters"].toObject()["originPointId"],vertex}},{"valueMm",10}});check(dimension.ok,dimension.error);placed=dimension.feature;bad=move(placed,5,-3,ids);check(!bad.ok && bad.feature==placed,"Placement dimension conflict is atomic");
 auto anchor=SketchGeometry::addStandalonePoint(sketch,{{"uMm",10},{"vMm",8}});check(anchor.ok,anchor.error);auto anchored=anchor.feature;const auto point=anchored["parameters"].toObject()["entities"].toArray().last().toObject()["pointId"].toString();auto relation=SketchGeometry::addConstraint(anchored,{{"type","coincident"},{"pointIds",QJsonArray{vertex,point}}});check(relation.ok,relation.error);anchored=relation.feature;bad=move(anchored,5,-3,ids);check(!bad.ok && bad.feature==anchored,"Relation to unselected free anchor cannot silently move it");
 auto disconnected=SketchGeometry::addRectangle(sketch,{{"u1Mm",-30},{"v1Mm",-30},{"u2Mm",-10},{"v2Mm",-18}});const auto disEdges=disconnected["parameters"].toObject()["entities"].toArray();bad=move(disconnected,5,-3,QJsonArray{ids[0],ids[1],disEdges[4].toObject()["id"],disEdges[5].toObject()["id"]});check(!bad.ok && bad.feature==disconnected,"Disconnected selection atomic");
 auto owned=SketchGeometry::addLine(sketch,{{"u1Mm",0},{"v1Mm",0},{"u2Mm",0},{"v2Mm",30}});const auto axis=owned["parameters"].toObject()["entities"].toArray().last().toObject().value("id");auto construction=SketchGeometry::setConstruction(owned,{{"entityIds",QJsonArray{axis}},{"construction",true}});check(construction.ok,construction.error);auto mirrored=SketchGeometry::mirrorEntities(construction.feature,{{"sourceEntityIds",ids},{"axisEntityId",axis}});check(mirrored.ok,mirrored.error);bad=move(mirrored.feature,5,-3,ids);check(!bad.ok && bad.feature==mirrored.feature,"Retained-owned source selection refused");
 check(doc.commit(SketchGeometry::replaceFeature(doc.authored(),second.feature),"Move Profile").isEmpty(),"Commit");const auto authored=doc.authored();doc.history().undo();doc.history().redo();check(doc.authored()==authored,"Exact document history");QTemporaryDir dir;const auto path=dir.filePath("move.alloy");check(doc.save(path).isEmpty(),"Save");CadDocument reopened;check(reopened.open(path).isEmpty() && reopened.authored()==authored,"Exact authored reopen");std::cout<<"SKETCH_MOVE_CORE_OK\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
